  1	import { z } from 'zod';
  2	import type Anthropic from '@anthropic-ai/sdk';
  3	import { config } from './config.ts';
  4	import { articles, bookedSlots, orders, products, shipments, slotTimes } from './data.ts';
  5	import { ToolError, TransientError } from './errors.ts';
  6	
  7	export interface ToolContext {
  8	  /** Park an action that changes customer data until the customer approves it in the UI. */
  9	  requestConfirmation(tool: string, summary: string, execute: () => unknown): { actionId: string };
 10	}
 11	
 12	export interface ToolSpec<S extends z.ZodType = z.ZodType> {
 13	  name: string;
 14	  description: string;
 15	  schema: S;
 16	  timeoutMs?: number;
 17	  retries?: number;
 18	  run(input: z.infer<S>, ctx: ToolContext): unknown | Promise<unknown>;
 19	}
 20	
 21	const defineTool = <S extends z.ZodType>(spec: ToolSpec<S>) => spec as unknown as ToolSpec;
 22	
 23	const RETURN_WINDOW_DAYS = 30;
 24	const CARD_RETURN_SHIPPING = 6.95;
 25	
 26	const orderId = z
 27	  .string()
 28	  .regex(/^[A-Za-z]\d{4}$/, 'Order numbers look like A1234')
 29	  .transform((s) => s.toUpperCase())
 30	  .describe('Order number, e.g. A1001');
 31	
 32	const daysBetween = (from: string, to: string) =>
 33	  Math.round((Date.parse(to) - Date.parse(from)) / 86_400_000);
 34	
 35	const addDays = (date: string, days: number) =>
 36	  new Date(Date.parse(date) + days * 86_400_000).toISOString().slice(0, 10);
 37	
 38	const maskEmail = (email: string) => email.replace(/^(.).*(@.*)$/, '$1***$2');
 39	
 40	function findOrder(id: string) {
 41	  const order = orders.find((o) => o.id === id);
 42	  if (!order) throw new ToolError(`No order ${id} exists. Ask the customer to double-check the order number.`);
 43	  return order;
 44	}
 45	
 46	const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
 47	// Simulates a flaky carrier API: the first request for a "-SLOW" parcel hangs past the timeout.
 48	const carrierAttempts = new Map<string, number>();
 49	
 50	export const tools: ToolSpec[] = [
 51	  defineTool({
 52	    name: 'lookup_order',
 53	    description:
 54	      'Get the status, items, dates and tracking number of an order. Use it before answering any question about a specific order.',
 55	    schema: z.object({ order_id: orderId }),
 56	    run: ({ order_id }) => {
 57	      const order = findOrder(order_id);
 58	      const total = order.items.reduce((sum, i) => sum + i.price * i.qty, 0);
 59	      return {
 60	        id: order.id,
 61	        customer_first_name: order.customer.split(' ')[0],
 62	        email: maskEmail(order.email),
 63	        status: order.status,
 64	        placed_at: order.placedAt,
 65	        delivered_at: order.deliveredAt ?? null,
 66	        tracking_number: order.trackingNumber ?? null,
 67	        items: order.items,
 68	        total_usd: total,
 69	        return_window_ends: order.deliveredAt ? addDays(order.deliveredAt, RETURN_WINDOW_DAYS) : null,
 70	      };
 71	    },
 72	  }),
 73	
 74	  defineTool({
 75	    name: 'track_shipment',
 76	    description: 'Get carrier tracking events and the estimated delivery date for a tracking number from lookup_order.',
 77	    schema: z.object({ tracking_number: z.string().min(4).describe('Tracking number, e.g. TRK-5501') }),
 78	    timeoutMs: 1500,
 79	    retries: 2,
 80	    run: async ({ tracking_number }) => {
 81	      const attempt = (carrierAttempts.get(tracking_number) ?? 0) + 1;
 82	      carrierAttempts.set(tracking_number, attempt);
 83	      await sleep(tracking_number.endsWith('-SLOW') && attempt === 1 ? 4000 : 120);
 84	      const shipment = shipments[tracking_number];
 85	      if (!shipment) throw new ToolError(`The carrier has no parcel with tracking number ${tracking_number}.`);
 86	      return { tracking_number, ...shipment, latest: shipment.events.at(-1) };
 87	    },
 88	  }),
 89	
 90	  defineTool({
 91	    name: 'check_stock',
 92	    description: 'Check price and stock by size or variant for a product, plus the restock date when sold out.',
 93	    schema: z.object({
 94	      product: z.string().min(2).describe('Product name or SKU, e.g. "Trail Runner 2" or "TR2"'),
 95	      variant: z.string().optional().describe('Size or variant, e.g. "42" or "M". Omit to list all variants.'),
 96	    }),
 97	    run: ({ product, variant }) => {
 98	      const q = product.toLowerCase();
 99	      const match = products.find((p) => p.sku.toLowerCase() === q || p.name.toLowerCase().includes(q));
100	      if (!match) {
101	        throw new ToolError(`No product matches "${product}". Known products: ${products.map((p) => p.name).join(', ')}.`);
102	      }
103	      if (variant !== undefined) {
104	        const key = Object.keys(match.stock).find((k) => k.toLowerCase() === variant.toLowerCase());
105	        if (!key) throw new ToolError(`${match.name} has no variant "${variant}". Variants: ${Object.keys(match.stock).join(', ')}.`);
106	        const units = match.stock[key];
107	        return { sku: match.sku, name: match.name, price_usd: match.price, variant: key, in_stock: units > 0, units, restock_date: units > 0 ? null : match.restockDate ?? 'unknown' };
108	      }
109	      return { sku: match.sku, name: match.name, price_usd: match.price, stock: match.stock, restock_date: match.restockDate ?? null };
110	    },
111	  }),
112	
113	  defineTool({
114	    name: 'search_help_center',
115	    description: 'Search store policies (returns, refunds, exchanges, shipping, warranty, cancellations). Quote the policy instead of guessing it.',
116	    schema: z.object({ query: z.string().min(3).describe('What to look for, e.g. "refund time"') }),
117	    run: ({ query }) => {
118	      const words = query.toLowerCase().split(/\W+/).filter((w) => w.length > 2);
119	      const scored = articles
120	        .map((a) => {
121	          const text = `${a.title} ${a.body}`.toLowerCase();
122	          return { a, score: words.filter((w) => text.includes(w)).length };
123	        })
124	        .filter((s) => s.score > 0)
125	        .sort((x, y) => y.score - x.score)
126	        .slice(0, 2);
127	      if (!scored.length) return { results: [], note: 'No matching article. Offer a callback with a human agent.' };
128	      return { results: scored.map(({ a }) => ({ id: a.id, title: a.title, text: a.body })) };
129	    },
130	  }),
131	
132	  defineTool({
133	    name: 'create_return_request',
134	    description:
135	      'Prepare a return for one item of a delivered order. It does NOT create the return by itself: the customer must approve it in the chat. Check the order and the returns policy first.',
136	    schema: z.object({
137	      order_id: orderId,
138	      sku: z.string().describe('SKU of the item to return, from lookup_order'),
139	      reason: z.enum(['wrong_size', 'defective', 'not_as_described', 'changed_mind', 'other']),
140	      refund_method: z.enum(['card', 'store_credit']),
141	    }),
142	    run: ({ order_id, sku, reason, refund_method }, ctx) => {
143	      const order = findOrder(order_id);
144	      if (order.status !== 'delivered' || !order.deliveredAt) {
145	        throw new ToolError(`Order ${order.id} is "${order.status}", only delivered orders can be returned.`);
146	      }
147	      const age = daysBetween(order.deliveredAt, config.today);
148	      if (age > RETURN_WINDOW_DAYS) {
149	        throw new ToolError(
150	          `Order ${order.id} was delivered ${age} days ago, outside the ${RETURN_WINDOW_DAYS}-day return window. Warranty may still apply to defects.`,
151	        );
152	      }
153	      const item = order.items.find((i) => i.sku.toLowerCase() === sku.toLowerCase());
154	      if (!item) throw new ToolError(`Order ${order.id} has no item ${sku}. Items: ${order.items.map((i) => i.sku).join(', ')}.`);
155	
156	      const shipping = refund_method === 'card' ? CARD_RETURN_SHIPPING : 0;
157	      const refund = Math.round((item.price * item.qty - shipping) * 100) / 100;
158	      const summary = `Return ${item.name} from order ${order.id} (${reason.replace('_', ' ')}), refund $${refund} to ${refund_method === 'card' ? 'card' : 'store credit'}`;
159	      const { actionId } = ctx.requestConfirmation('create_return_request', summary, () => {
160	        const returnId = `R-${order.id.slice(1)}-${item.sku}`;
161	        return {
162	          return_id: returnId,
163	          label_url: `https://returns.example.com/labels/${returnId}.pdf`,
164	          refund_usd: refund,
165	          refund_method,
166	          instructions: 'Print the label, pack the item unworn in its original box and drop it at any UPS point within 14 days.',
167	        };
168	      });
169	      return {
170	        status: 'awaiting_customer_approval',
171	        action_id: actionId,
172	        summary,
173	        note: 'The customer now sees Approve / Decline buttons. Do not say the return is created until a system note confirms it.',
174	      };
175	    },
176	  }),
177	
178	  defineTool({
179	    name: 'get_callback_slots',
180	    description: 'List free phone-callback slots with a human support agent for a date.',
181	    schema: z.object({ date: z.iso.date().describe('Date as YYYY-MM-DD') }),
182	    run: ({ date }) => {
183	      if (date <= config.today) throw new ToolError(`Callbacks can be booked from tomorrow (${addDays(config.today, 1)}).`);
184	      return { date, free: slotTimes.filter((t) => !bookedSlots.has(`${date} ${t}`)) };
185	    },
186	  }),
187	
188	  defineTool({
189	    name: 'book_callback',
190	    description: 'Book a phone callback with a human support agent. Needs a date, a free time slot and a phone number.',
191	    schema: z.object({
192	      date: z.iso.date().describe('Date as YYYY-MM-DD'),
193	      time: z.enum(slotTimes as [string, ...string[]]).describe('One of the fixed slot times'),
194	      phone: z.string().regex(/^\+?[\d\s()-]{7,20}$/, 'Phone number with country code, e.g. +1 555 0142'),
195	      topic: z.string().max(200).describe('Short reason for the call'),
196	    }),
197	    run: ({ date, time, phone, topic }) => {
198	      if (date <= config.today) throw new ToolError(`Callbacks can be booked from tomorrow (${addDays(config.today, 1)}).`);
199	      const key = `${date} ${time}`;
200	      if (bookedSlots.has(key)) {
201	        const free = slotTimes.filter((t) => !bookedSlots.has(`${date} ${t}`));
202	        throw new ToolError(`${time} on ${date} is already taken. Free slots that day: ${free.join(', ') || 'none'}.`);
203	      }
204	      bookedSlots.add(key);
205	      return { booking_id: `CB-${date.replaceAll('-', '')}-${time.replace(':', '')}`, date, time, phone, topic };
206	    },
207	  }),
208	];
