210	export const toolByName = new Map(tools.map((t) => [t.name, t]));
211	
212	/** Tool definitions in the Anthropic Messages API format, generated from the zod schemas. */
213	export function anthropicTools(): Anthropic.Tool[] {
214	  return tools.map((t) => {
215	    const { $schema: _ignored, ...schema } = z.toJSONSchema(t.schema, { io: 'input' }) as Record<string, unknown>;
216	    return { name: t.name, description: t.description, input_schema: schema as Anthropic.Tool.InputSchema };
217	  });
218	}
