220	export { ToolError, TransientError };
  1	import { z } from 'zod';
  2	import { ToolError, TransientError } from './errors.ts';
  3	import { toolByName, type ToolContext } from './tools.ts';
  4	
  5	export interface ToolOutcome {
  6	  ok: boolean;
  7	  output?: unknown;
  8	  error?: string;
  9	  latencyMs: number;
 10	  attempts: number;
 11	}
 12	
 13	const DEFAULT_TIMEOUT_MS = 5000;
 14	
 15	const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
 16	
 17	function withTimeout<T>(work: Promise<T>, ms: number, name: string): Promise<T> {
 18	  let timer: NodeJS.Timeout | undefined;
 19	  const timeout = new Promise<never>((_, reject) => {
 20	    timer = setTimeout(() => reject(new TransientError(`${name} did not answer within ${ms} ms`)), ms);
 21	  });
 22	  return Promise.race([work, timeout]).finally(() => clearTimeout(timer));
 23	}
 24	
 25	function log(entry: Record<string, unknown>) {
 26	  if (process.env.VITEST) return;
 27	  console.log(JSON.stringify({ ts: new Date().toISOString(), event: 'tool_call', ...entry }));
 28	}
 29	
 30	/**
 31	 * Runs one tool call requested by the model: validates the input, applies a timeout,
 32	 * retries transient failures with backoff, and turns every failure into a message
 33	 * the model can act on instead of an exception that kills the conversation.
 34	 */
 35	export async function executeTool(name: string, input: unknown, ctx: ToolContext): Promise<ToolOutcome> {
 36	  const started = performance.now();
 37	  const finish = (outcome: Omit<ToolOutcome, 'latencyMs'>): ToolOutcome => {
 38	    const result = { ...outcome, latencyMs: Math.round(performance.now() - started) };
 39	    log({ tool: name, ok: result.ok, latencyMs: result.latencyMs, attempts: result.attempts, error: result.error });
 40	    return result;
 41	  };
 42	
 43	  const tool = toolByName.get(name);
 44	  if (!tool) {
 45	    return finish({ ok: false, attempts: 0, error: `Unknown tool "${name}". Available tools: ${[...toolByName.keys()].join(', ')}.` });
 46	  }
 47	
 48	  const parsed = tool.schema.safeParse(input);
 49	  if (!parsed.success) {
 50	    return finish({ ok: false, attempts: 0, error: `Invalid parameters for ${name}:\n${z.prettifyError(parsed.error)}` });
 51	  }
 52	
 53	  const maxAttempts = (tool.retries ?? 0) + 1;
 54	  for (let attempt = 1; ; attempt++) {
 55	    try {
 56	      const output = await withTimeout(
 57	        Promise.resolve().then(() => tool.run(parsed.data, ctx)),
 58	        tool.timeoutMs ?? DEFAULT_TIMEOUT_MS,
 59	        name,
 60	      );
 61	      return finish({ ok: true, output, attempts: attempt });
 62	    } catch (err) {
 63	      if (err instanceof TransientError && attempt < maxAttempts) {
 64	        await sleep(200 * 2 ** (attempt - 1));
 65	        continue;
 66	      }
 67	      if (err instanceof ToolError) return finish({ ok: false, attempts: attempt, error: err.message });
 68	      if (err instanceof TransientError) {
 69	        return finish({ ok: false, attempts: attempt, error: `${err.message}. The system is temporarily unavailable, offer a callback instead.` });
 70	      }
 71	      console.error(`[${name}] unexpected failure`, err);
 72	      return finish({ ok: false, attempts: attempt, error: 'Internal error in this tool. Apologise and offer a callback with a human agent.' });
 73	    }
 74	  }
 75	}
  1	import { randomUUID } from 'node:crypto';
  2	import type Anthropic from '@anthropic-ai/sdk';
  3	import { executeTool } from './executor.ts';
  4	import { systemPrompt } from './prompt.ts';
  5	import { anthropicTools, type ToolContext } from './tools.ts';
  6	
  7	export type TraceEvent =
  8	  | { type: 'model_call'; step: number; model: string }
  9	  | { type: 'thinking'; text: string }
 10	  | { type: 'tool_call'; id: string; name: string; input: unknown }
 11	  | { type: 'tool_result'; id: string; name: string; ok: boolean; output?: unknown; error?: string; latencyMs: number; attempts: number }
 12	  | { type: 'confirmation_required'; actionId: string; tool: string; summary: string }
 13	  | { type: 'assistant_text'; text: string }
 14	  | { type: 'usage'; inputTokens: number; outputTokens: number; costUsd: number; totalCostUsd: number }
 15	  | { type: 'done'; stopReason: string }
 16	  | { type: 'error'; message: string };
 17	
 18	export type Emit = (event: TraceEvent) => void;
 19	
 20	/** The only part of the Anthropic client the agent needs, which keeps it easy to fake in tests. */
 21	export interface MessagesClient {
 22	  messages: { create(params: Anthropic.MessageCreateParamsNonStreaming): Promise<Anthropic.Message> };
 23	}
 24	
 25	export interface AgentOptions {
 26	  model: string;
 27	  maxTokens: number;
 28	  maxSteps: number;
 29	  priceInPerMTok: number;
 30	  priceOutPerMTok: number;
 31	  today: string;
 32	}
 33	
 34	interface PendingAction {
 35	  tool: string;
 36	  summary: string;
 37	  execute: () => unknown;
 38	}
 39	
 40	export class Session {
 41	  messages: Anthropic.MessageParam[] = [];
 42	  pending = new Map<string, PendingAction>();
 43	  totalCostUsd = 0;
 44	  busy = false;
 45	}
 46	
 47	export class SupportAgent {
 48	  private readonly tools = anthropicTools();
 49	
 50	  constructor(
 51	    private readonly client: MessagesClient,
 52	    private readonly opts: AgentOptions,
 53	  ) {}
 54	
 55	  async send(session: Session, text: string, emit: Emit) {
 56	    session.messages.push({ role: 'user', content: text });
 57	    await this.loop(session, emit);
 58	  }
 59	
 60	  /** Called when the customer presses Approve or Decline on a parked action. */
 61	  async resolve(session: Session, actionId: string, approve: boolean, emit: Emit) {
 62	    const action = session.pending.get(actionId);
 63	    if (!action) {
 64	      emit({ type: 'error', message: 'This action has expired or was already handled.' });
 65	      emit({ type: 'done', stopReason: 'error' });
 66	      return;
 67	    }
 68	    session.pending.delete(actionId);
 69	
 70	    let note = `The customer declined action ${actionId} (${action.summary}). Nothing was changed.`;
 71	    if (approve) {
 72	      const started = performance.now();
 73	      try {
 74	        const output = await action.execute();
 75	        emit({ type: 'tool_result', id: actionId, name: action.tool, ok: true, output, latencyMs: Math.round(performance.now() - started), attempts: 1 });
 76	        note = `The customer approved action ${actionId} (${action.summary}) and it was executed. Result: ${JSON.stringify(output)}`;
 77	      } catch (err) {
 78	        const message = err instanceof Error ? err.message : String(err);
 79	        emit({ type: 'tool_result', id: actionId, name: action.tool, ok: false, error: message, latencyMs: Math.round(performance.now() - started), attempts: 1 });
 80	        note = `The customer approved action ${actionId}, but it failed: ${message}`;
 81	      }
 82	    }
 83	    session.messages.push({ role: 'user', content: `[System note, not written by the customer] ${note}` });
 84	    await this.loop(session, emit);
 85	  }
 86	
 87	  private async loop(session: Session, emit: Emit) {
 88	    const ctx: ToolContext = {
 89	      requestConfirmation: (tool, summary, execute) => {
 90	        const actionId = `act_${randomUUID().slice(0, 8)}`;
 91	        session.pending.set(actionId, { tool, summary, execute });
 92	        emit({ type: 'confirmation_required', actionId, tool, summary });
 93	        return { actionId };
 94	      },
 95	    };
 96	
 97	    for (let step = 1; step <= this.opts.maxSteps; step++) {
 98	      emit({ type: 'model_call', step, model: this.opts.model });
 99	      const response = await this.client.messages.create({
100	        model: this.opts.model,
101	        max_tokens: this.opts.maxTokens,
102	        system: systemPrompt(this.opts.today),
103	        tools: this.tools,
104	        messages: session.messages,
105	      });
106	      this.trackUsage(session, response.usage, emit);
107	
108	      // The assistant turn goes back verbatim: tool_use ids and thinking blocks must round-trip.
109	      session.messages.push({ role: 'assistant', content: response.content as Anthropic.ContentBlockParam[] });
110	
111	      const results: Anthropic.ToolResultBlockParam[] = [];
112	      for (const block of response.content) {
113	        if (block.type === 'thinking' && block.thinking.trim()) {
114	          emit({ type: 'thinking', text: block.thinking.trim() });
115	        } else if (block.type === 'text' && block.text.trim()) {
116	          emit({ type: 'assistant_text', text: block.text.trim() });
117	        } else if (block.type === 'tool_use') {
118	          emit({ type: 'tool_call', id: block.id, name: block.name, input: block.input });
119	          const outcome = await executeTool(block.name, block.input, ctx);
120	          emit({ type: 'tool_result', id: block.id, name: block.name, ...outcome });
121	          results.push({
122	            type: 'tool_result',
123	            tool_use_id: block.id,
124	            content: JSON.stringify(outcome.ok ? outcome.output : { error: outcome.error }),
125	            is_error: !outcome.ok,
126	          });
127	        }
128	      }
129	
130	      if (results.length === 0) {
131	        emit({ type: 'done', stopReason: response.stop_reason ?? 'end_turn' });
132	        return;
133	      }
134	      session.messages.push({ role: 'user', content: results });
135	    }
136	
137	    const text = 'Sorry, this request needs more steps than I am allowed to take. A human agent will follow up by email.';
138	    session.messages.push({ role: 'assistant', content: text });
139	    emit({ type: 'assistant_text', text });
140	    emit({ type: 'done', stopReason: 'max_steps' });
141	  }
142	
143	  private trackUsage(session: Session, usage: Anthropic.Usage, emit: Emit) {
144	    const inputTokens = usage.input_tokens ?? 0;
145	    const outputTokens = usage.output_tokens ?? 0;
146	    const costUsd = (inputTokens * this.opts.priceInPerMTok + outputTokens * this.opts.priceOutPerMTok) / 1_000_000;
147	    session.totalCostUsd += costUsd;
148	    emit({ type: 'usage', inputTokens, outputTokens, costUsd, totalCostUsd: session.totalCostUsd });
149	  }
150	}
